<?php
defined('ABSPATH')||exit;
final class GDO_Frontend{
	public function hooks(){add_shortcode('gdo_doctor_application',array($this,'form'));add_action('admin_post_gdo_submit_application',array($this,'precheck'),1);add_action('admin_post_gdo_submit_application',array($this,'submit'));}
	public function form(){if(!is_user_logged_in()){return '<div class="gdo-notice"><h2>Create or log in to your account</h2><p>Any qualified doctor may begin an application. Google Account login is supported by File 02.</p><a class="gdo-button" href="'.esc_url(wp_login_url(get_permalink())).'">Log In</a></div>';}$id=get_current_user_id();$status=GDO_Helpers::status($id);$docs=GDO_Helpers::documents($id);ob_start();?><main class="gdo-shell"><header class="gdo-head"><span>Global Professional Application</span><h1>Doctor Application and Verification</h1><p>Complete every required field and upload encrypted credential evidence. Public listing begins only after manual approval.</p></header><section class="gdo-progress"><strong><?php echo absint(GDO_Helpers::completion($id));?>%</strong><div><span style="width:<?php echo absint(GDO_Helpers::completion($id));?>%"></span></div><p>Current review status: <b><?php echo esc_html(SPD_Helpers::status_label($status));?></b></p></section><?php if($docs):?><section class="gdo-docs"><h2>Submitted Documents</h2><ul><?php foreach($docs as $doc):?><li><?php echo esc_html(GDO_Helpers::types()[$doc->document_type]);?> — received <?php echo esc_html($doc->uploaded_at);?> UTC</li><?php endforeach;?></ul></section><?php endif;?><form class="gdo-form" action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="gdo_submit_application"><?php wp_nonce_field('gdo_submit_application','gdo_nonce');?><label>Full professional name<input name="display_name" required value="<?php echo esc_attr(get_the_author_meta('display_name',$id));?>"></label><?php foreach(array('country'=>'Country','city'=>'City','clinic'=>'Clinic or professional address','qualification'=>'Primary qualification','licence_number'=>'License or registration number','licensing_authority'=>'Licensing authority','experience_years'=>'Years of professional experience','specialty'=>'Professional specialty','languages'=>'Languages','consultation_modes'=>'Consultation methods','phone'=>'Phone number','whatsapp'=>'WhatsApp number') as $key=>$label):?><label><?php echo esc_html($label);?><input name="<?php echo esc_attr($key);?>" required value="<?php echo esc_attr(SPD_Helpers::get($id,$key));?>"></label><?php endforeach;?><label class="gdo-wide">Professional biography<textarea name="bio" required><?php echo esc_textarea(SPD_Helpers::get($id,'bio'));?></textarea></label><?php foreach(GDO_Helpers::types() as $key=>$label):?><label class="gdo-file"><?php echo esc_html($label);?><?php echo GDO_Helpers::has_document($id,$key)?'<small>Already received. Upload only to replace.</small>':'<small>Required: PDF, JPG, PNG, or WebP; maximum 5 MB.</small>';?><input type="file" name="document_<?php echo esc_attr($key);?>" accept="application/pdf,image/jpeg,image/png,image/webp" <?php echo GDO_Helpers::has_document($id,$key)?'':'required';?>></label><?php endforeach;?><label class="gdo-check gdo-wide"><input type="checkbox" name="truth_confirm" value="1" required> I certify that the information and documents are authentic, current, and belong to me.</label><label class="gdo-check gdo-wide"><input type="checkbox" name="privacy_confirm" value="1" required> I consent to secure processing of my professional and identity documents for manual verification.</label><label class="gdo-check gdo-wide"><input type="checkbox" name="conduct_confirm" value="1" required> I agree not to publish misleading credentials, cure guarantees, or unsafe medical claims.</label><button class="gdo-button" type="submit">Submit Application for Review</button></form><p class="gdo-disclaimer">Verification confirms that the platform reviewed submitted evidence. It is not a guarantee of treatment outcomes and does not replace licensing checks required in a patient’s jurisdiction.</p></main><?php return ob_get_clean();}
	public function submit(){if(!is_user_logged_in()){wp_die(esc_html__('Log in to submit an application.','global-doctor-onboarding'),'',array('response'=>403));}check_admin_referer('gdo_submit_application','gdo_nonce');if(empty($_POST['truth_confirm'])||empty($_POST['privacy_confirm'])||empty($_POST['conduct_confirm'])){wp_die(esc_html__('All declarations are required.','global-doctor-onboarding'),'',array('response'=>400));}$id=get_current_user_id();$name=isset($_POST['display_name'])?sanitize_text_field(wp_unslash($_POST['display_name'])):'';if(!$name){wp_die(esc_html__('Professional name is required.','global-doctor-onboarding'),'',array('response'=>400));}wp_update_user(array('ID'=>$id,'display_name'=>$name));foreach(array_merge(GDO_Helpers::fields(),array('licensing_authority')) as $key){$v=isset($_POST[$key])?wp_unslash($_POST[$key]):'';$v='bio'===$key?sanitize_textarea_field($v):sanitize_text_field($v);if(!trim($v)){wp_die(esc_html__('Complete every required professional field.','global-doctor-onboarding'),'',array('response'=>400));}if(in_array($key,array('phone','whatsapp'),true)){$v=SPD_Helpers::clean_phone($v);}update_user_meta($id,'_spd_'.$key,$v);}foreach(GDO_Helpers::types() as $type=>$label){$this->upload($id,$type);}foreach(array_keys(GDO_Helpers::types()) as $type){if(!GDO_Helpers::has_document($id,$type)){wp_die(esc_html__('All three credential documents are required.','global-doctor-onboarding'),'',array('response'=>400));}}update_user_meta($id,'_spd_account_type','doctor');update_user_meta($id,'_sa_account_type','doctor');update_user_meta($id,'_spd_verification_status','under_review');update_user_meta($id,'_gdo_submitted_at',current_time('mysql',true));$u=new WP_User($id);$u->remove_role('sabri_doctor_verified');$u->add_role('sabri_doctor_pending');SPD_Helpers::audit($id,'application','under_review','Complete credential application submitted');wp_mail(get_option('admin_email'),'Doctor Application Submitted','A doctor application is ready for review. User ID: '.$id);wp_safe_redirect(add_query_arg('submitted','1',GDO_Helpers::page()));exit;}
	private function upload($user,$type){$key='document_'.$type;if(empty($_FILES[$key]['tmp_name'])){return;}$f=$_FILES[$key];if(UPLOAD_ERR_OK!==(int)$f['error']||(int)$f['size']>5*MB_IN_BYTES){wp_die(esc_html__('A credential file is invalid or exceeds 5 MB.','global-doctor-onboarding'),'',array('response'=>400));}$mimes=array('pdf'=>'application/pdf','jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp');$check=wp_check_filetype_and_ext($f['tmp_name'],$f['name'],$mimes);$mime=!empty($check['type'])?$check['type']:'';if(!in_array($mime,$mimes,true)){wp_die(esc_html__('Credential files must be PDF, JPG, PNG, or WebP.','global-doctor-onboarding'),'',array('response'=>400));}$bytes=file_get_contents($f['tmp_name']);$encrypted=GDO_Helpers::encrypt($bytes);if(false===$encrypted){wp_die(esc_html__('The credential could not be encrypted.','global-doctor-onboarding'),'',array('response'=>500));}$storage=wp_generate_uuid4().'.gdo';$path=trailingslashit(GDO_Helpers::storage()).$storage;if(false===file_put_contents($path,$encrypted,LOCK_EX)){wp_die(esc_html__('The encrypted credential could not be stored.','global-doctor-onboarding'),'',array('response'=>500));}global $wpdb;$old=GDO_Helpers::documents($user);foreach($old as $doc){if($doc->document_type===$type){$oldpath=trailingslashit(GDO_Helpers::storage()).basename($doc->storage_name);if(is_file($oldpath)){unlink($oldpath);}$wpdb->delete($wpdb->prefix.'gdo_documents',array('id'=>$doc->id),array('%d'));}}$wpdb->insert($wpdb->prefix.'gdo_documents',array('user_id'=>$user,'document_type'=>$type,'original_name'=>sanitize_file_name($f['name']),'mime_type'=>$mime,'file_size'=>(int)$f['size'],'storage_name'=>$storage,'uploaded_at'=>current_time('mysql',true)),array('%d','%s','%s','%s','%d','%s','%s'));}
	public function precheck(){if(is_user_logged_in()&&!absint(SPD_Helpers::get(get_current_user_id(),'profile_photo_id',0))){wp_die(esc_html__('Add a professional profile photograph in Edit Core Profile before submitting verification.','global-doctor-onboarding'),'',array('response'=>400,'back_link'=>true));}}
}
